const form=document.querySelector('#note-form'),status=document.querySelector('#note-status'),button=form.querySelector('button[type=submit]');let config=null,token='';
try{const r=await fetch('/api/config');config=await r.json();if(!config.correspondence){button.disabled=true;status.textContent='The preview’s message channel is not enabled yet. The email address above remains available.'}else if(config.turnstileSiteKey){const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.async=true;script.onload=()=>window.turnstile.render('#note-verification',{sitekey:config.turnstileSiteKey,callback:value=>token=value,'expired-callback':()=>token=''});document.head.append(script)}}catch{status.textContent='The message service is unavailable. The email address above remains available.';button.disabled=true}
form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;button.disabled=true;status.textContent='Saving your note…';const fields=new FormData(form);try{const r=await fetch('/api/inquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:fields.get('name'),email:fields.get('email'),message:fields.get('message'),website:fields.get('website'),agree:fields.get('agree')==='on',turnstileToken:token})});const data=await r.json();if(!r.ok)throw new Error(data.error||'The note could not be saved.');status.textContent='Your note has been saved for Sub.';form.reset();if(window.turnstile)window.turnstile.reset()}catch(error){status.textContent=error.message}finally{button.disabled=false}});
